struct State { entries: HashMap<String, Entry> }

impl State {   // methods never lock: the guard is the precondition
    fn find(&mut self, key: &str) -> Entry { /* lookup, insert on miss */ }
}

struct Cache { state: Mutex<State> }

impl Cache {
    fn find(&self, key: &str) -> Entry {
        self.state.lock().unwrap().find(key)   // one acquisition at the border
    }
}
